source='''from collections import Counter

def transform(grid):
    """Add a full line of color 8 just beyond the object, away from color-2 divider."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    divider = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not divider:
        return g
    counts = Counter(v for row in g for v in row if v not in (2, 8))
    background = counts.most_common(1)[0][0]
    obj = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (background, 2, 8)]
    if not obj:
        return g
    rows = {r for r, c in divider}
    cols = {c for r, c in divider}
    if len(cols) <= len(rows):
        minc, maxc = min(c for r, c in obj), max(c for r, c in obj)
        line = max(c for r, c in divider) + 1 if max(c for r, c in divider) < minc else minc - 1
        if 0 <= line < w:
            for r in range(h):
                g[r][line] = 8
    else:
        minr, maxr = min(r for r, c in obj), max(r for r, c in obj)
        line = max(r for r, c in divider) + 1 if max(r for r, c in divider) < minr else minr - 1
        if 0 <= line < h:
            for c in range(w):
                g[line][c] = 8
    return g
'''
